import { useEffect, useRef, useState, type ReactNode } from "react";
import {
  ConvexProvider,
  ConvexReactClient,
  useConvex,
  useMutation,
  useQuery,
} from "convex/react";
import { api } from "../convex/_generated/api";

const env = import.meta.env;
const REGIONS = [
  { id: "us", label: "USA", aws: "aws-us-east-1", url: env.VITE_CONVEX_URL_US },
  { id: "eu", label: "EU", aws: "aws-eu-west-1", url: env.VITE_CONVEX_URL_EU },
  { id: "au", label: "Australia", aws: "aws-ap-southeast-2", url: env.VITE_CONVEX_URL_AU },
  { id: "ca", label: "Canada", aws: "aws-ca-central-1", url: env.VITE_CONVEX_URL_CA },
]
  .filter((r): r is typeof r & { url: string } => typeof r.url === "string")
  .map((r) => ({ ...r, client: new ConvexReactClient(r.url) }));
type Region = (typeof REGIONS)[number];

const MAX = 1000; // matches take(1000) in convex/items.ts

type Stats = { n: number; p50: number; p95: number; max: number; total: number };
type Net = { ws: number; http: number; echoSmall: number; echoBig: number; mbps: number };
type Handlers = { insert: () => void; del: () => void; net: () => Promise<void> };

// Each panel registers its actions here so the top bar can drive all regions at once.
const handlers = new Map<string, Handlers>();

const time = async (f: () => Promise<unknown>) => {
  const t = performance.now();
  await f();
  return performance.now() - t;
};
const pct = (sorted: number[], p: number) =>
  sorted[Math.min(sorted.length - 1, Math.floor(sorted.length * p))];
const median = (xs: number[]) => pct([...xs].sort((a, b) => a - b), 0.5);
const stats = (lat: number[], total: number): Stats => {
  const s = [...lat].sort((a, b) => a - b);
  return { n: s.length, p50: pct(s, 0.5), p95: pct(s, 0.95), max: s[s.length - 1], total };
};
const ms = (x: number) => `${Math.round(x)} ms`;

export default function App() {
  const [n, setN] = useState(50);
  const [netBusy, setNetBusy] = useState(false);
  const all = (f: (h: Handlers) => void) => handlers.forEach(f);
  const netAll = async () => {
    setNetBusy(true);
    // ponytail: sequential so the 4MB echoes don't share bandwidth and skew MB/s
    for (const h of handlers.values()) await h.net();
    setNetBusy(false);
  };

  return (
    <main className="p-4 md:p-8 flex flex-col gap-6">
      <header className="flex flex-wrap items-end gap-3">
        <h1 className="text-2xl font-bold mr-auto">Convex region latency</h1>
        <label className="flex flex-col text-sm gap-1">
          Processes (N)
          <input
            type="number"
            min={1}
            max={MAX}
            value={n}
            onChange={(e) => setN(Math.max(1, Math.min(MAX, Number(e.target.value) || 1)))}
            className="w-28 px-2 py-1 rounded-md border-2 border-slate-300 dark:border-slate-700 bg-transparent"
          />
        </label>
        <Button onClick={() => all((h) => h.insert())}>Insert N everywhere</Button>
        <Button onClick={() => all((h) => h.del())}>Delete all everywhere</Button>
        <Button onClick={() => void netAll()} disabled={netBusy}>
          {netBusy ? "Testing…" : "Network test everywhere"}
        </Button>
      </header>
      {REGIONS.length < 4 && (
        <p className="text-amber-600 text-sm">
          Some VITE_CONVEX_URL_US/EU/AU/CA values are missing from .env.local.
        </p>
      )}
      <div className="grid gap-4 grid-cols-1 md:grid-cols-2 xl:grid-cols-4">
        {REGIONS.map((r) => (
          <ConvexProvider key={r.id} client={r.client}>
            <RegionPanel region={r} n={n} />
          </ConvexProvider>
        ))}
      </div>
      <p className="text-xs text-slate-500">
        Latency = mutation sent → change pushed back to this browser over the
        subscription. Measured from your location. DNS/TCP checks: <code>pnpm run nettest</code>.
      </p>
    </main>
  );
}

function RegionPanel({ region, n }: { region: Region; n: number }) {
  const convex = useConvex();
  const items = useQuery(api.items.list);
  const add = useMutation(api.items.add);
  const remove = useMutation(api.items.remove);
  // key (insert) or _id (delete) → performance.now() when the mutation was sent
  const pending = useRef(new Map<string, number>());
  const run = useRef<{ kind: "insert" | "delete"; start: number; lat: number[] } | null>(null);
  const [busy, setBusy] = useState<"insert" | "delete" | "net" | null>(null);
  const [results, setResults] = useState<{ insert?: Stats; delete?: Stats; net?: Net }>({});
  const [error, setError] = useState<string | null>(null);

  // Timestamp changes when the client receives them, not after React renders.
  useEffect(() => {
    const watch = convex.watchQuery(api.items.list, {});
    return watch.onUpdate(() => {
      const r = run.current;
      const list = watch.localQueryResult();
      if (!r || !list) return;
      const now = performance.now();
      const present = new Set(list.map((i) => (r.kind === "insert" ? i.key : i._id)));
      for (const [k, sentAt] of pending.current) {
        if (present.has(k) === (r.kind === "insert")) {
          r.lat.push(now - sentAt);
          pending.current.delete(k);
        }
      }
      if (pending.current.size === 0) {
        const kind = r.kind;
        setResults((prev) => ({ ...prev, [kind]: stats(r.lat, now - r.start) }));
        run.current = null;
        setBusy(null);
      }
    });
  }, [convex]);

  const fail = (e: unknown) => {
    run.current = null;
    pending.current.clear();
    setBusy(null);
    setError(String(e));
  };

  const start = (kind: "insert" | "delete") => {
    setError(null);
    setBusy(kind);
    pending.current.clear();
    run.current = { kind, start: performance.now(), lat: [] };
  };

  // ponytail: the Convex client runs one client's mutations in order, so with N
  // in flight the later ones include queueing. That's what a real client sees.
  const insert = () => {
    if (run.current || items === undefined) return;
    const count = Math.min(n, MAX - items.length);
    if (count <= 0) return setError(`Delete first (max ${MAX} items).`);
    start("insert");
    for (let i = 0; i < count; i++) {
      const key = crypto.randomUUID();
      pending.current.set(key, performance.now());
      add({ key }).catch(fail);
    }
  };

  const del = () => {
    if (run.current || !items?.length) return;
    start("delete");
    for (const { _id } of items) {
      pending.current.set(_id, performance.now());
      remove({ id: _id }).catch(fail);
    }
  };

  // Browser half of `npx convex network-test`: same /instance_name and /echo endpoints.
  const net = async () => {
    setError(null);
    setBusy("net");
    try {
      const ws: number[] = [];
      const http: number[] = [];
      for (let i = 0; i < 5; i++) ws.push(await time(() => convex.query(api.items.ping, { nonce: Math.random() })));
      for (let i = 0; i < 5; i++) http.push(await time(() => fetch(`${region.url}/instance_name`)));
      const echo = async (size: number) => {
        const body = new Uint8Array(size);
        // random bytes so a compressing proxy can't inflate throughput
        for (let i = 0; i < size; i += 65536) crypto.getRandomValues(body.subarray(i, i + 65536));
        return time(async () => {
          const res = await fetch(`${region.url}/echo`, { method: "POST", body });
          const got = (await res.arrayBuffer()).byteLength;
          if (got !== size) throw new Error(`echo returned ${got}/${size} bytes`);
        });
      };
      const echoSmall = await echo(128);
      const big = 4 * 1024 * 1024;
      const echoBig = await echo(big);
      const net = { ws: median(ws), http: median(http), echoSmall, echoBig, mbps: (big * 2) / 1e6 / (echoBig / 1000) };
      setResults((prev) => ({ ...prev, net }));
    } catch (e) {
      setError(String(e));
    }
    setBusy(null);
  };

  useEffect(() => {
    handlers.set(region.id, { insert, del, net });
    return () => void handlers.delete(region.id);
  });

  const { insert: ins, delete: dl, net: nt } = results;
  return (
    <section className="flex flex-col gap-3 p-4 rounded-md bg-slate-100 dark:bg-slate-800">
      <div>
        <h2 className="text-lg font-bold">{region.label}</h2>
        <p className="text-xs font-mono text-slate-500">{region.aws}</p>
      </div>
      <div className="flex flex-wrap gap-2">
        <Button onClick={insert} disabled={busy !== null}>Insert {n}</Button>
        <Button onClick={del} disabled={busy !== null}>Delete all</Button>
        <Button onClick={() => void net()} disabled={busy !== null}>Net test</Button>
      </div>
      <p className="text-sm">
        Items: <b>{items?.length ?? "…"}</b>
        {busy && <span className="ml-2 text-slate-500">{busy}…</span>}
      </p>
      <div className="flex flex-wrap gap-px min-h-6 content-start" aria-hidden>
        {items?.map((i) => <span key={i._id} className="w-1.5 h-1.5 bg-emerald-500" />)}
      </div>
      <table className="text-sm">
        <tbody>
          <Row label="Insert p50 / p95" value={ins && `${ms(ins.p50)} / ${ms(ins.p95)}`} />
          <Row label={`Insert max · all ${ins?.n ?? ""} visible`} value={ins && `${ms(ins.max)} · ${ms(ins.total)}`} />
          <Row label="Delete p50 / p95" value={dl && `${ms(dl.p50)} / ${ms(dl.p95)}`} />
          <Row label={`Delete max · all ${dl?.n ?? ""} gone`} value={dl && `${ms(dl.max)} · ${ms(dl.total)}`} />
          <Row label="WS query RTT (median)" value={nt && ms(nt.ws)} />
          <Row label="HTTP RTT (median)" value={nt && ms(nt.http)} />
          <Row label="Echo 128B" value={nt && ms(nt.echoSmall)} />
          <Row label="Echo 4MB" value={nt && `${ms(nt.echoBig)} · ${nt.mbps.toFixed(1)} MB/s`} />
        </tbody>
      </table>
      {error && <p className="text-sm text-red-600">{error}</p>}
    </section>
  );
}

function Row({ label, value }: { label: string; value?: string }) {
  return (
    <tr>
      <td className="pr-2 text-slate-500">{label}</td>
      <td className="text-right font-mono">{value ?? "—"}</td>
    </tr>
  );
}

function Button({ children, ...props }: { children: ReactNode; onClick: () => void; disabled?: boolean }) {
  return (
    <button
      {...props}
      className="bg-dark dark:bg-light text-light dark:text-dark text-sm px-3 py-1.5 rounded-md disabled:opacity-40"
    >
      {children}
    </button>
  );
}

