import { v } from "convex/values";
import { query, mutation } from "./_generated/server";

export const list = query({
  args: {},
  returns: v.array(
    v.object({ _id: v.id("items"), _creationTime: v.number(), key: v.string() }),
  ),
  handler: async (ctx) => {
    const items = await ctx.db.query("items").order("desc").take(1000);
    return items.map(({ _id, _creationTime, key }) => ({ _id, _creationTime, key }));
  },
});

export const add = mutation({
  args: { key: v.string() },
  returns: v.null(),
  handler: async (ctx, { key }) => {
    await ctx.db.insert("items", { key });
    return null;
  },
});

export const remove = mutation({
  args: { id: v.id("items") },
  returns: v.null(),
  handler: async (ctx, { id }) => {
    if (await ctx.db.get("items", id)) await ctx.db.delete("items", id);
    return null;
  },
});

// Round-trip probe for the network test. nonce defeats the client's query dedupe.
export const ping = query({
  args: { nonce: v.number() },
  returns: v.null(),
  handler: async () => null,
});

// Server wall clock, so the client can split latency into "to server" vs "back to browser".
export const clock = mutation({
  args: {},
  returns: v.number(),
  handler: async () => Date.now(),
});
