import { useEffect, useRef, useState } from "react";
import { useConvex, useMutation, useQuery } from "convex/react";
import type { FunctionReturnType } from "convex/server";
import { api } from "../convex/_generated/api";
import { MAX, type Region } from "./regions";
import { median, stats, time, type Net, type Results } from "./lib/stats";

export type Item = FunctionReturnType<typeof api.items.list>[number];
// total = sent → seen in this browser. up = sent → server write (needs clock offset).
export type Timing = { total: number; up?: number };
export type Pending = { key: string; sentAt: number };
export type Busy = "insert" | "delete" | "net" | null;
export type Commands = { insert: (n: number) => void; del: () => void; net: () => Promise<void> };

// Each region section registers its actions here so the sidebar can drive all regions.
export const commands = new Map<string, Commands>();

const EMPTY: Item[] = [];
const epoch = () => performance.timeOrigin + performance.now();

export function useRegionBench(region: Region, onResult: (id: string, patch: Results) => void) {
  const convex = useConvex();
  const raw = useQuery(api.items.list);
  const add = useMutation(api.items.add);
  const remove = useMutation(api.items.remove);
  const clock = useMutation(api.items.clock);

  // key (insert) or _id (delete) → epoch ms when the mutation was sent
  const sent = useRef(new Map<string, number>());
  const run = useRef<{ kind: "insert" | "delete"; total: number; start: number; lat: number[] } | null>(null);
  const offset = useRef<number | null>(null); // server clock − client clock

  const [pending, setPending] = useState<Pending[]>([]);
  const [timings, setTimings] = useState<Record<string, Timing>>({});
  const [busy, setBusy] = useState<Busy>(null);
  const [progress, setProgress] = useState<{ done: number; total: number } | null>(null);
  const [error, setError] = useState<string | null>(null);

  // NTP-style offset estimate: keep the sample with the smallest round trip.
  useEffect(() => {
    let cancelled = false;
    void (async () => {
      let best = Infinity;
      for (let i = 0; i < 3 && !cancelled; i++) {
        const t0 = epoch();
        const server = await clock({});
        const t1 = epoch();
        if (t1 - t0 < best) {
          best = t1 - t0;
          offset.current = server - (t0 + t1) / 2;
        }
      }
    })().catch(() => {});
    return () => {
      cancelled = true;
    };
  }, [clock]);

  // Timestamp changes when the client receives them, not after React renders.
  useEffect(() => {
    const watch = convex.watchQuery(api.items.list, {});
    return watch.onUpdate(() => {
      const r = run.current;
      const list = watch.localQueryResult();
      if (!r || !list) return;
      const now = epoch();
      const isInsert = r.kind === "insert";
      const byKey = new Map(list.map((i) => [isInsert ? i.key : i._id, i]));
      const seen: Record<string, Timing> = {};
      for (const [k, sentAt] of sent.current) {
        const item = byKey.get(k);
        if (Boolean(item) !== isInsert) continue;
        const total = now - sentAt;
        const up =
          item && offset.current !== null
            ? Math.min(total, Math.max(0, item._creationTime - offset.current - sentAt))
            : undefined;
        seen[k] = { total, up };
        r.lat.push(total);
        sent.current.delete(k);
      }
      if (Object.keys(seen).length > 0) {
        setTimings((prev) => ({ ...prev, ...seen }));
        if (isInsert) setPending((prev) => prev.filter((p) => !(p.key in seen)));
        setProgress({ done: r.lat.length, total: r.total });
      }
      if (sent.current.size === 0) {
        const s = stats(r.lat, now - r.start);
        onResult(region.id, isInsert ? { insert: s } : { delete: s });
        run.current = null;
        setBusy(null);
      }
    });
  }, [convex, region.id, onResult]);

  const fail = (e: unknown) => {
    run.current = null;
    sent.current.clear();
    setPending([]);
    setBusy(null);
    setError(String(e));
  };

  const begin = (kind: "insert" | "delete", total: number) => {
    setError(null);
    setBusy(kind);
    setProgress({ done: 0, total });
    sent.current.clear();
    run.current = { kind, total, start: epoch(), lat: [] };
  };

  // ponytail: the Convex client runs one client's mutations in order, so with N
  // in flight the later ones include queueing. That's what a real client sees.
  const insert = (n: number) => {
    if (run.current || raw === undefined) return;
    const count = Math.min(n, MAX - raw.length);
    if (count <= 0) return setError(`Delete first (max ${MAX} rows).`);
    begin("insert", count);
    const batch: Pending[] = [];
    for (let i = 0; i < count; i++) {
      const p = { key: crypto.randomUUID(), sentAt: epoch() };
      batch.push(p);
      sent.current.set(p.key, p.sentAt);
      add({ key: p.key }).catch(fail);
    }
    setPending(batch.reverse()); // newest first, like the table
  };

  const del = () => {
    if (run.current || !raw?.length) return;
    begin("delete", raw.length);
    for (const { _id } of raw) {
      sent.current.set(_id, epoch());
      remove({ id: _id }).catch(fail);
    }
  };

  // Browser half of `npx convex network-test`: same /instance_name and /echo endpoints.
  const net = async () => {
    setError(null);
    setBusy("net");
    try {
      const ws: number[] = [];
      const http: number[] = [];
      for (let i = 0; i < 5; i++) ws.push(await time(() => convex.query(api.items.ping, { nonce: Math.random() })));
      for (let i = 0; i < 5; i++) http.push(await time(() => fetch(`${region.url}/instance_name`)));
      const echo = async (size: number) => {
        const body = new Uint8Array(size);
        // random bytes so a compressing proxy can't inflate throughput
        for (let i = 0; i < size; i += 65536) crypto.getRandomValues(body.subarray(i, i + 65536));
        return time(async () => {
          const res = await fetch(`${region.url}/echo`, { method: "POST", body });
          const got = (await res.arrayBuffer()).byteLength;
          if (got !== size) throw new Error(`echo returned ${got}/${size} bytes`);
        });
      };
      const echoSmall = await echo(128);
      const big = 4 * 1024 * 1024;
      const echoBig = await echo(big);
      const result: Net = { ws: median(ws), http: median(http), echoSmall, echoBig, mbps: big / 1e6 / (echoBig / 1000) };
      onResult(region.id, { net: result });
    } catch (e) {
      setError(String(e));
    }
    setBusy(null);
  };

  return { items: raw ?? EMPTY, loaded: raw !== undefined, pending, timings, busy, progress, error, insert, del, net };
}

export type Bench = ReturnType<typeof useRegionBench>;

