import { cx, ms, tone } from "../lib/format";
import type { Item, Timing } from "../useRegionBench";

const BARS = 120;

// One bar per row, oldest → newest, height = sent → seen latency.
export function LatencyHistogram({ items, timings }: { items: Item[]; timings: Record<string, Timing> }) {
  const values = items
    .slice(0, BARS)
    .reverse()
    .map((i) => ({ id: i._id, ms: timings[i.key]?.total }));
  const max = Math.max(500, ...values.map((v) => v.ms ?? 0));

  return (
    <div className="flex flex-col gap-1 px-4 py-3">
      <div className="flex h-16 items-end gap-px">
        {values.length === 0 && <div className="h-px w-full bg-white/10" />}
        {values.map((v) => (
          <div
            key={v.id}
            title={v.ms === undefined ? "not timed by this tab" : ms(v.ms)}
            style={{ height: `${Math.max(4, ((v.ms ?? max * 0.05) / max) * 100)}%` }}
            className={cx(
              "min-w-px flex-1 origin-bottom rounded-t-[2px] animate-pop transition-[height] duration-300 motion-reduce:animate-none",
              tone(v.ms),
              v.ms === undefined && "opacity-30",
            )}
          />
        ))}
      </div>
      <div className="flex justify-between font-mono text-[11px] text-slate-500">
        <span>last {Math.min(BARS, items.length)} writes</span>
        <span>max {ms(max)}</span>
      </div>
    </div>
  );
}
