import { useEffect, useState } from "react";
import type { Region } from "../regions";
import { clockTime, cx, ms } from "../lib/format";
import type { Item, Pending, Timing } from "../useRegionBench";

type Shown = Item & { ghost?: boolean };

// Keeps deleted rows on screen for a moment so they can animate out.
function useWithGhosts(items: Item[]) {
  const [prev, setPrev] = useState(items);
  const [shown, setShown] = useState<Shown[]>(items);
  if (items !== prev) {
    setPrev(items);
    const live = new Set(items.map((i) => i._id));
    const had = new Set(shown.map((s) => s._id));
    setShown([
      ...items.filter((i) => !had.has(i._id)), // new rows are newest → top
      ...shown.map((s) => (live.has(s._id) ? s : { ...s, ghost: true })),
    ]);
  }
  const hasGhosts = shown.some((s) => s.ghost);
  useEffect(() => {
    if (!hasGhosts) return;
    // ponytail: one timer, reset while deletes keep landing, so the batch fades out together
    const t = setTimeout(() => setShown((s) => s.filter((x) => !x.ghost)), 900);
    return () => clearTimeout(t);
  }, [shown, hasGhosts]);
  return shown;
}

export function EventTable({
  region,
  items,
  pending,
  timings,
}: {
  region: Region;
  items: Item[];
  pending: Pending[];
  timings: Record<string, Timing>;
}) {
  const rows = useWithGhosts(items);
  const scale = Math.max(500, ...rows.map((r) => timings[r.key]?.total ?? 0));

  return (
    <div className="min-h-0 flex-1 overflow-auto">
      <table className="w-full border-collapse font-mono text-[13px]">
        <thead className="sticky top-0 z-10 bg-slate-950/95 text-left text-xs font-medium text-slate-400 backdrop-blur">
          <tr className="[&>th]:border-b [&>th]:border-white/10 [&>th]:px-3 [&>th]:py-2 [&>th]:font-medium">
            <th className="w-8" />
            <th>Time</th>
            <th>Status</th>
            <th>Method</th>
            <th>Key</th>
            <th className="text-right">Latency</th>
            <th>Region</th>
            <th className="w-48">Timing phases</th>
          </tr>
        </thead>
        <tbody className="[&>tr]:border-b [&>tr]:border-white/5 [&_td]:px-3 [&_td]:py-1.5">
          {pending.map((p) => (
            <tr key={p.key} className="text-slate-500">
              <td><Square className="bg-slate-500 animate-pulse" /></td>
              <td>{clockTime(p.sentAt)}</td>
              <td>SENT</td>
              <td>INSERT</td>
              <td>{p.key.slice(0, 8)}</td>
              <td className="text-right">…</td>
              <td><RegionCell region={region} /></td>
              <td><div className="h-3 w-full animate-pulse rounded-sm bg-white/5" /></td>
            </tr>
          ))}
          {rows.map((r) => {
            const t = r.ghost ? timings[r._id] : timings[r.key];
            return (
              <tr
                key={r._id}
                className={cx(
                  "transition-colors hover:bg-white/[0.03] motion-reduce:animate-none",
                  r.ghost ? "animate-row-out" : "animate-row-in",
                )}
              >
                <td><Square className={r.ghost ? "bg-rose-500" : "bg-emerald-400"} /></td>
                <td className="text-slate-300">{clockTime(r._creationTime)}</td>
                <td className={r.ghost ? "text-rose-400" : "text-emerald-400"}>{r.ghost ? "GONE" : "OK"}</td>
                <td className="text-slate-300">{r.ghost ? "DELETE" : "INSERT"}</td>
                <td className="text-slate-400">{r.key.slice(0, 8)}</td>
                <td className="text-right tabular-nums text-slate-100">
                  {t ? <>{Math.round(t.total).toLocaleString()}<span className="text-slate-500">ms</span></> : <span className="text-slate-600">—</span>}
                </td>
                <td><RegionCell region={region} /></td>
                <td><Phases timing={t} scale={scale} ghost={r.ghost} /></td>
              </tr>
            );
          })}
          {rows.length === 0 && pending.length === 0 && (
            <tr>
              <td colSpan={8} className="py-16 text-center font-sans text-sm text-slate-500">
                No rows yet. Insert some to watch them arrive.
              </td>
            </tr>
          )}
        </tbody>
      </table>
    </div>
  );
}

function Square({ className }: { className: string }) {
  return <span className={cx("block size-2 rounded-[2px]", className)} />;
}

function RegionCell({ region }: { region: Region }) {
  return (
    <span className="whitespace-nowrap">
      <span className="text-slate-200">{region.code}</span>{" "}
      <span className="font-sans text-xs text-slate-500">{region.city}</span>
    </span>
  );
}

// Sky = sent → written on the server. Violet = server → pushed to this browser.
function Phases({ timing, scale, ghost }: { timing?: Timing; scale: number; ghost?: boolean }) {
  if (!timing) return <div className="h-3 w-full rounded-sm bg-white/[0.03]" />;
  const width = (timing.total / scale) * 100;
  const up = timing.up === undefined ? 0 : (timing.up / timing.total) * 100;
  return (
    <div className="h-3 w-full rounded-sm bg-white/[0.03]" title={phaseTitle(timing)}>
      <div className="flex h-full overflow-hidden rounded-sm transition-[width] duration-500" style={{ width: `${width}%` }}>
        {ghost ? (
          <div className="h-full w-full bg-gradient-to-r from-rose-500/70 to-rose-400" />
        ) : (
          <>
            <div className="h-full bg-gradient-to-r from-sky-500 to-cyan-400" style={{ width: `${up}%` }} />
            <div className="h-full flex-1 bg-gradient-to-r from-violet-500 to-fuchsia-500" />
          </>
        )}
      </div>
    </div>
  );
}

const phaseTitle = (t: Timing) =>
  t.up === undefined
    ? `total ${ms(t.total)}`
    : `to server ${ms(t.up)} · back to browser ${ms(t.total - t.up)} · total ${ms(t.total)}`;
