import { useEffect } from "react";
import type { Region } from "../regions";
import { ms } from "../lib/format";
import type { Results } from "../lib/stats";
import { commands, useRegionBench } from "../useRegionBench";
import { EventTable } from "./EventTable";
import { LatencyHistogram } from "./LatencyHistogram";
import { Button, LiveDot, Metric } from "./ui";

// One full-viewport screen per region.
export function RegionSection({
  region,
  n,
  results,
  onResult,
}: {
  region: Region;
  n: number;
  results?: Results;
  onResult: (id: string, patch: Results) => void;
}) {
  const b = useRegionBench(region, onResult);

  useEffect(() => {
    commands.set(region.id, b);
    return () => void commands.delete(region.id);
  });

  const { insert: ins, delete: del, net } = results ?? {};
  const running = b.busy === "insert" || b.busy === "delete";

  return (
    <section id={`region-${region.id}`} className="flex h-screen snap-start flex-col border-b border-white/10">
      <header className="flex flex-wrap items-center gap-3 border-b border-white/10 px-4 py-3">
        <span className="text-2xl leading-none">{region.flag}</span>
        <div className="mr-auto">
