            <LiveDot busy={b.busy !== null} loaded={b.loaded} />
          </h2>
          <p className="font-mono text-xs text-slate-500">
            {region.aws} · {region.city}
          </p>
        </div>
        <span className="font-mono text-xs text-slate-400">
          {running && b.progress
            ? `${b.progress.done} / ${b.progress.total} seen`
            : `${b.items.length.toLocaleString()} rows`}
        </span>
        <Button variant="primary" onClick={() => b.insert(n)} disabled={b.busy !== null}>
          Insert {n}
        </Button>
        <Button variant="danger" onClick={b.del} disabled={b.busy !== null || b.items.length === 0}>
          Delete all
        </Button>
        <Button onClick={() => void b.net()} disabled={b.busy !== null}>
          {b.busy === "net" ? "Testing…" : "Network test"}
        </Button>
      </header>

      <div className="h-0.5 bg-white/5">
        <div
          className="h-full bg-sky-400 transition-[width] duration-200"
          style={{ width: running && b.progress ? `${(b.progress.done / b.progress.total) * 100}%` : "0%" }}
        />
      </div>

      <div className="grid grid-cols-2 border-b border-white/10 sm:grid-cols-4 xl:grid-cols-8">
        <Metric label="Write → seen p50" value={ins && ms(ins.p50)} />
        <Metric label="Write p95" value={ins && ms(ins.p95)} />
        <Metric label={`All ${ins?.n ?? ""} visible`} value={ins && ms(ins.total)} />
        <Metric label="Delete p50" value={del && ms(del.p50)} />
        <Metric label={`All ${del?.n ?? ""} gone`} value={del && ms(del.total)} />
        <Metric label="WS round trip" value={net && ms(net.ws)} />
        <Metric label="HTTP round trip" value={net && ms(net.http)} />
        <Metric label="4 MB echo" value={net && `${net.mbps.toFixed(1)} MB/s`} />
      </div>

      <div className="border-b border-white/10">
        <LatencyHistogram items={b.items} timings={b.timings} />
      </div>

      {b.error && <p className="border-b border-rose-500/30 bg-rose-500/10 px-4 py-2 text-sm text-rose-300">{b.error}</p>}

      <EventTable region={region} items={b.items} pending={b.pending} timings={b.timings} />
    </section>
  );
}
