import { useCallback, useEffect, useRef, useState } from "react";
import { ConvexProvider } from "convex/react";
import { REGIONS } from "./regions";
import type { Results } from "./lib/stats";
import { commands } from "./useRegionBench";
import { RegionSection } from "./components/RegionSection";
import { Sidebar } from "./components/Sidebar";

export default function App() {
  const [n, setN] = useState(50);
  const [results, setResults] = useState<Record<string, Results | undefined>>({});
  const [active, setActive] = useState(REGIONS[0]?.id);
  const [netBusy, setNetBusy] = useState(false);
  const scroller = useRef<HTMLDivElement>(null);

  const onResult = useCallback(
    (id: string, patch: Results) => setResults((prev) => ({ ...prev, [id]: { ...prev[id], ...patch } })),
    [],
  );

  // Highlight the region currently filling the screen.
  useEffect(() => {
    const root = scroller.current;
    if (!root) return;
    const io = new IntersectionObserver(
      (entries) => entries.forEach((e) => e.isIntersecting && setActive(e.target.id.replace("region-", ""))),
      { root, threshold: 0.55 },
    );
    root.querySelectorAll("section[id^=region-]").forEach((s) => io.observe(s));
    return () => io.disconnect();
  }, []);

  const netAll = async () => {
    setNetBusy(true);
    // ponytail: sequential so the 4MB echoes don't share bandwidth and skew MB/s
    for (const c of commands.values()) await c.net();
    setNetBusy(false);
  };

  return (
    <div className="md:flex md:h-screen">
      <Sidebar
        n={n}
        setN={setN}
        results={results}
        active={active}
        onJump={(id) => document.getElementById(`region-${id}`)?.scrollIntoView({ behavior: "smooth" })}
        onInsertAll={() => commands.forEach((c) => c.insert(n))}
        onDeleteAll={() => commands.forEach((c) => c.del())}
        onNetAll={() => void netAll()}
        netBusy={netBusy}
      />
      <main ref={scroller} className="h-screen min-w-0 flex-1 snap-y snap-mandatory overflow-y-auto">
        {REGIONS.length < 4 && (
          <p className="bg-amber-500/10 px-4 py-2 text-sm text-amber-300">
            Some VITE_CONVEX_URL_US/EU/AU/CA values are missing from .env.local.
          </p>
        )}
        {REGIONS.map((r) => (
          <ConvexProvider key={r.id} client={r.client}>
            <RegionSection region={r} n={n} results={results[r.id]} onResult={onResult} />
          </ConvexProvider>
        ))}
      </main>
    </div>
  );
}
