import { useEffect, useState } from "react";
import { cx, ms, tone } from "../lib/format";
import type { Item } from "../useRegionBench";

type Tile = Item & { ghost?: boolean };

// One square per row. New squares pop in at the end; deleted ones stay a moment to shrink away.
export function TileGrid({ items, latency }: { items: Item[]; latency: Record<string, number> }) {
  const [prev, setPrev] = useState(items);
  const [tiles, setTiles] = useState<Tile[]>(() => [...items].reverse());
  if (items !== prev) {
    setPrev(items);
    const live = new Set(items.map((i) => i._id));
    const had = new Set(tiles.map((t) => t._id));
    setTiles([
      ...tiles.map((t) => (live.has(t._id) ? t : { ...t, ghost: true })),
      ...[...items].reverse().filter((i) => !had.has(i._id)), // list is newest-first
    ]);
  }

  const hasGhosts = tiles.some((t) => t.ghost);
  useEffect(() => {
    if (!hasGhosts) return;
    // ponytail: one timer, reset while deletes keep landing, so the batch clears together
    const t = setTimeout(() => setTiles((ts) => ts.filter((x) => !x.ghost)), 500);
    return () => clearTimeout(t);
  }, [tiles, hasGhosts]);

  if (tiles.length === 0) {
    return <p className="m-auto text-sm text-slate-600">Empty. Hit Insert.</p>;
  }
  return (
    <div className="flex flex-wrap content-start gap-1">
      {tiles.map((t) => (
        <span
          key={t._id}
          title={latency[t.key] === undefined ? undefined : ms(latency[t.key])}
          className={cx(
            "size-3 rounded-[3px] motion-reduce:animate-none",
            t.ghost ? "bg-rose-500 animate-vanish" : cx(tone(latency[t.key]), "animate-pop"),
          )}
        />
      ))}
    </div>
  );
}
