import { REGIONS, type Region } from "../regions";
import { cx, ms } from "../lib/format";
import { median, type Net, type Results } from "../lib/stats";
import { Chip } from "../components/ui";

type Metric = {
  title: string;
  hint: string;
  lowerIsBetter: boolean;
  format: (v: number) => string;
  value: (id: string) => number | undefined;
};

// One ranked bar chart per metric, best first. Bar length = the measured value,
// so for latency the shortest bar wins; for throughput the longest does.
export function CompareView({
  latency,
  net,
  onGo,
}: {
  latency: Record<string, Results | undefined>;
  net: Record<string, Required<Net> | undefined>;
  onGo: (tab: "latency" | "network") => void;
}) {
  const metrics: Metric[] = [
    { title: "Write → seen", hint: "median, lower is better", lowerIsBetter: true, format: ms, value: (id) => latency[id]?.insert?.p50 },
    { title: "All rows deleted", hint: "total, lower is better", lowerIsBetter: true, format: ms, value: (id) => latency[id]?.delete?.total },
    { title: "WebSocket round trip", hint: "median, lower is better", lowerIsBetter: true, format: ms, value: (id) => net[id] && median(net[id].wsSamples) },
    { title: "HTTP round trip", hint: "median, lower is better", lowerIsBetter: true, format: ms, value: (id) => net[id] && median(net[id].httpSamples) },
    { title: "4 MB echo", hint: "throughput, higher is better", lowerIsBetter: false, format: (v) => `${v.toFixed(1)} MB/s`, value: (id) => net[id]?.mbps },
  ];

  // Overall: which region wins the most metrics that have at least 2 regions measured.
  const wins = new Map<string, number>();
  for (const m of metrics) {
    const best = ranked(m)[0];
    if (best && ranked(m).length > 1) wins.set(best.region.id, (wins.get(best.region.id) ?? 0) + 1);
  }
  const contested = metrics.filter((m) => ranked(m).length > 1).length;
  const leader = [...wins].sort((a, b) => b[1] - a[1])[0];
  const leaderRegion = REGIONS.find((r) => r.id === leader?.[0]);

  return (
    <div className="flex min-h-0 flex-1 flex-col">
      <div className="flex flex-wrap items-center gap-2 border-b border-line px-4 py-2 text-[13px] text-muted">
        <span className="mr-auto">
          {leaderRegion ? (
            <>
              Fastest overall:{" "}
              <span key={leaderRegion.id} className="text-neutral-100 animate-flash">
                {leaderRegion.flag} {leaderRegion.label}
              </span>{" "}
              · wins {leader![1]} of {contested} metrics
            </>
          ) : (
            "Run both tabs, then compare regions here."
          )}
        </span>
        <Chip onClick={() => onGo("latency")}>Run latency</Chip>
        <Chip onClick={() => onGo("network")}>Run network test</Chip>
      </div>

      <main className="mx-auto grid w-full max-w-6xl flex-1 auto-rows-min grid-cols-1 gap-3 overflow-y-auto p-3 md:grid-cols-2">
        {metrics.map((m) => (
          <RankChart key={m.title} metric={m} rows={ranked(m)} />
        ))}
      </main>
    </div>
  );

  function ranked(m: Metric) {
    return REGIONS.flatMap((region) => {
      const v = m.value(region.id);
      return v === undefined ? [] : [{ region, v }];
    }).sort((a, b) => (m.lowerIsBetter ? a.v - b.v : b.v - a.v));
  }
}

function RankChart({ metric, rows }: { metric: Metric; rows: { region: Region; v: number }[] }) {
  const max = Math.max(...rows.map((r) => r.v));
  return (
    <section className="flex flex-col gap-3 rounded-lg border border-line bg-panel p-4">
      <header>
        <h2 className="text-sm font-medium text-neutral-100">{metric.title}</h2>
        <p className="text-xs text-muted">{metric.hint}</p>
      </header>
      {rows.length === 0 ? (
        <p className="py-4 text-[13px] text-muted">No data yet.</p>
      ) : (
        <ol className="flex flex-col gap-2">
          {rows.map(({ region, v }, i) => {
            const best = i === 0 && rows.length > 1;
            return (
              <li
                key={region.id}
                title={`${region.label}: ${metric.format(v)}`}
                className="grid grid-cols-[7.5rem_1fr_6rem] items-center gap-3 text-[13px]"
              >
                <span className="flex items-center gap-2 text-neutral-300">
                  <span>{region.flag}</span>
                  {region.label}
                </span>
                <span className="h-5">
                  {/* Square at the baseline, 4px rounded data-end; grows in on mount. */}
                  <span
                    className={cx(
                      "block h-full origin-left rounded-r-[4px] transition-[width] duration-500 animate-grow motion-reduce:animate-none",
                      best ? "bg-emerald-400" : "bg-neutral-500",
                    )}
                    style={{ width: `${Math.max(2, (v / max) * 100)}%` }}
                  />
                </span>
                <span className="text-right font-mono tabular-nums text-neutral-200">
                  {metric.format(v)}
                  {best && <span className="ml-1.5 text-xs text-emerald-300">★</span>}
                </span>
              </li>
            );
          })}
        </ol>
      )}
    </section>
  );
}
